package com.quantumlock.audit;

import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "audit_event")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class AuditEvent {

    @Id
    @GeneratedValue(strategy = GenerationType.AUTO)
    private UUID id;

    // sequence is auto-generated by DB (BIGSERIAL)
    @Column(insertable = false, updatable = false)
    private Long sequence;

    @Column(name = "chain_position", nullable = false)
    private Long chainPosition;

    @Column(name = "tenant_id", nullable = false)
    private UUID tenantId;

    @Column(name = "actor_id")
    private UUID actorId;

    @Column(name = "actor_name", length = 255)
    private String actorName;

    @Column(length = 255)
    private String actor;

    @Column(name = "resource_type", length = 100)
    private String resourceType;

    @Column(name = "resource_id")
    private UUID resourceId;

    @Column(nullable = false, length = 100)
    private String action;

    @Column(name = "operation_id")
    private UUID operationId;

    @Column(name = "policy_version")
    private Long policyVersion;

    @Column(nullable = false, length = 50)
    @Builder.Default
    private String outcome = "SUCCESS";

    @Column
    private String detail;

    @Column(name = "previous_hash", length = 255)
    private String previousHash;

    @Column(name = "event_hash", nullable = false, length = 255)
    private String eventHash;

    @Column(name = "created_at", nullable = false, updatable = false)
    @Builder.Default
    private Instant createdAt = Instant.now();
}
